export function diseasesOf(species: string): DiseaseRecord[] {
  return DISEASE_MASTER.filter(function (d) { return d.species === species; });
}
export function diseasesByCategory(species: string): Record<string, DiseaseRecord[]> {
  const map: Record<string, DiseaseRecord[]> = {};
  for (const d of DISEASE_MASTER) if (d.species===species) { (map[d.category]||(map[d.category]=[])).push(d); }
  return map;
}